CREATE TABLE membership_statuses (id text PRIMARY KEY, name text NOT NULL UNIQUE, position integer NOT NULL DEFAULT 0);
INSERT INTO membership_statuses(id,name,position) VALUES ('pending','Awaiting payment',0),('active','Active',1),('paused','Paused',2),('past_due','Renewal failed',3),('canceled','Cancelled',4),('expired','Expired',5),('unknown','Awaiting confirmation',6);
CREATE TABLE plan_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
INSERT INTO plan_categories(name) VALUES ('Studio'),('Community');
CREATE TABLE plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, price integer NOT NULL CHECK(price>0 AND price<=10000000), currency text NOT NULL DEFAULT 'GBP' CHECK(currency IN ('GBP','USD','EUR','INR')), period text NOT NULL CHECK(period IN ('day','week','month','year')), one_off boolean NOT NULL DEFAULT false, perks text NOT NULL DEFAULT '', category_id uuid NOT NULL REFERENCES plan_categories(id), available boolean NOT NULL DEFAULT true);
INSERT INTO plans(name,price,period,one_off,perks,category_id) SELECT 'Everyday',4500,'month',false,'Unlimited studio visits · Community events',id FROM plan_categories WHERE name='Studio';
INSERT INTO plans(name,price,period,one_off,perks,category_id) SELECT 'Day pass',1200,'day',true,'One day of studio access',id FROM plan_categories WHERE name='Studio';
CREATE TABLE members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES app_users(id), name text NOT NULL, email text NOT NULL UNIQUE, code text NOT NULL UNIQUE DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES members(id), plan_id uuid NOT NULL REFERENCES plans(id), status_id text NOT NULL DEFAULT 'pending' REFERENCES membership_statuses(id), starts_at timestamptz NOT NULL DEFAULT now(), renews_at timestamptz, cancel_at_end boolean NOT NULL DEFAULT false, price integer NOT NULL, currency text NOT NULL, period text NOT NULL, one_off boolean NOT NULL, customer_ref text, billing_ref text UNIQUE, checkout_ref text UNIQUE, operation_key uuid NOT NULL DEFAULT gen_random_uuid(), action_key uuid, pending_action text, notice_status text NOT NULL DEFAULT 'not-sent', UNIQUE(member_id));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), membership_id uuid NOT NULL REFERENCES memberships(id), reference text NOT NULL UNIQUE, amount integer NOT NULL, currency text NOT NULL, paid_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE check_ins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES members(id), staff_id uuid NOT NULL REFERENCES app_users(id), visited_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE member_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES members(id), author_id uuid NOT NULL REFERENCES app_users(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX check_ins_member ON check_ins(member_id,visited_at);
CREATE TABLE membership_emails (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), membership_id uuid NOT NULL REFERENCES memberships(id), event text NOT NULL, email text NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'not-sent', UNIQUE(membership_id,event));
